\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Samsung Color Theme ──
\definecolor{primary}{HTML}{0A0A1A}        % Deep navy/black
\definecolor{secondary}{HTML}{1428A0}       % Samsung blue
\definecolor{accent}{HTML}{0070F3}          % Lighter Samsung blue
\definecolor{gold}{HTML}{D4AF37}            % Premium flagship accent
\definecolor{bgposter}{HTML}{0D0D1A}        % Dark background
\definecolor{bluebg}{HTML}{0F1A3D}          % Card tint
\definecolor{goldbg}{HTML}{1A1500}          % Gold tint for flagship
\definecolor{bluecard}{HTML}{0C1830}        % Blue card tint
\definecolor{textwhite}{HTML}{FFFFFF}
\definecolor{textsilver}{HTML}{C0C0C0}
\definecolor{stathighlight}{HTML}{1A2A4A}
\definecolor{newbg}{HTML}{1A3D1A}           % Green for NEW badge

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=4pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=4pt, topsep=4pt,
  label={\color{gold}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  samsungcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluecard,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{gold},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=goldbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={gold!50},
    valign=top, drop shadow={opacity=0.25},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textsilver},
    coltitle=textsilver, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  newcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=newbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=newbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!30!white,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=secondary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=24, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row5}{
  {\fontsize{72}{86}\selectfont\bfseries SAMSUNG GALAXY}\\[8pt]
  {\fontsize{60}{72}\selectfont\bfseries\textcolor{secondary}{ECOSYSTEM 2025}}\\[12pt]
  {\fontsize{28}{34}\selectfont\textcolor{textsilver}{Innovation Across Every Category}}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!15!bgposter, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row5 and row7}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 7+}\\
      {\fontsize{22}{28}\selectfont\color{textwhite} Product Categories}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{gold!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{gold} 14}\\
      {\fontsize{22}{28}\selectfont\color{textwhite} Featured Products}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 2 NEW}\\
      {\fontsize{22}{28}\selectfont\color{textwhite} Flagship Launches}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 4+}\\
      {\fontsize{22}{28}\selectfont\color{textwhite} AI-Branded Products}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ HERO PRODUCT: Galaxy S26 Ultra ══
\posterbox[
  goldcard, title={Galaxy S26 Ultra}
]{name=herophone, column=1, between=row7 and row13}{
  \centering
  \vspace{4pt}
  \colorbox{gold!15}{\parbox{0.92\linewidth}{%
    \centering
    {\fontsize{22}{28}\selectfont\color{gold}\bfseries NEW FLAGSHIP}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textsilver} Smartphone 2025}
  }}\\[6pt]
  \fontsize{28}{36}\selectfont
  \begin{itemize}
    \item Pro-grade camera system
    \item Integrated S Pen
    \item Galaxy AI powered
    \item Premium materials
  \end{itemize}
}

% ══ HERO PRODUCT: Galaxy Buds4 Pro ══
\posterbox[
  newcard, title={Galaxy Buds4 Pro}
]{name=herobuds, column=2, between=row7 and row13}{
  \centering
  \vspace{4pt}
  \colorbox{accent!15}{\parbox{0.92\linewidth}{%
    \centering
    {\fontsize{22}{28}\selectfont\color{accent}\bfseries NEW FLAGSHIP}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textsilver} Audio 2025}
  }}\\[6pt]
  \fontsize{28}{36}\selectfont
  \begin{itemize}
    \item Next-gen ANC
    \item High-fidelity audio
    \item Seamless Galaxy pairing
    \item Premium sound quality
  \end{itemize}
}

% ══ ECOSYSTEM OVERVIEW ══
\posterbox[
  samsungcard, title={Complete Ecosystem}
]{name=ecosystem, column=3, between=row7 and row13}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}
    \item Smartphones
    \item Foldables
    \item Tablets
    \item Wearables
    \item Audio
    \item TVs
    \item Home Appliances
  \end{itemize}
}

% ══ AI INTEGRATION ══
\posterbox[
  highlightcard, title={AI-Powered Innovation}
]{name=ai, column=1, span=3, between=row13 and row16}{
  \centering
  \fontsize{28}{36}\selectfont
  \colorbox{secondary!25}{\parbox{0.45\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{gold} Galaxy AI}\\
    {\fontsize{22}{28}\selectfont\color{textsilver} S26 Ultra, Z Fold7, Z Flip7}\\
    {\fontsize{18}{24}\selectfont\color{textsilver} On-device intelligence, photography, translation}\vspace{6pt}%
  }}\hfill
  \colorbox{accent!25}{\parbox{0.45\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{gold} Bespoke AI}\\
    {\fontsize{22}{28}\selectfont\color{textsilver} Refrigerator, Laundry, Home}\\
    {\fontsize{18}{24}\selectfont\color{textsilver} Smart energy, pattern learning, automation}\vspace{6pt}%
  }}
}

% ══ PRODUCT CATEGORY TABLE ══
\posterbox[
  darkcard, title={Category Highlights}
]{name=table, column=1, span=3, between=row16 and row22}{
  \fontsize{24}{30}\selectfont
  \begin{center}
    \rowcolors{1}{primary!20}{primary!10}
    \begin{tabular}{|p{120mm}|p{200mm}|p{100mm}|p{120mm}|}
      \rowcolor{secondary!30}
      {\fontsize{24}{30}\selectfont\bfseries\color{textwhite} Category} & {\fontsize{24}{30}\selectfont\bfseries\color{textwhite} Product} & {\fontsize{24}{30}\selectfont\bfseries\color{textwhite} Status} & {\fontsize{24}{30}\selectfont\bfseries\color{textwhite} AI} \\[6pt]
      \rowcolor{primary!20}
      Smartphone & Galaxy S26 Ultra & \textcolor{gold}{NEW} & Galaxy AI \\
      \rowcolor{primary!10}
      Foldables & Galaxy Z Fold7 & Current & Galaxy AI \\
      \rowcolor{primary!20}
      Foldables & Galaxy Z Flip7 & Current & Galaxy AI \\
      \rowcolor{primary!10}
      Tablets & Galaxy Tab S11 Series & Current & Galaxy AI \\
      \rowcolor{primary!20}
      Wearables & Galaxy Watch Ultra & Current & - \\
      \rowcolor{primary!10}
      Audio & Galaxy Buds4 Pro & \textcolor{gold}{NEW} & - \\
      \rowcolor{primary!20}
      TV & Neo QLED 8K TV & Current & - \\
      \rowcolor{primary!10}
      TV & The Frame Pro & Current & - \\
      \rowcolor{primary!20}
      Audio & Q-series Soundbar & Current & - \\
      \rowcolor{primary!10}
      Monitors & Odyssey OLED G9 & Current & - \\
      \rowcolor{primary!20}
      Kitchen & Bespoke AI Refrigerator & Current & Bespoke AI \\
      \rowcolor{primary!10}
      Laundry & Bespoke AI Laundry & Current & Bespoke AI \\
      \rowcolor{primary!20}
      Cleaning & Jet Stick Vacuums & Current & - \\
      \rowcolor{primary!10}
      Climate & Air Conditioners & Current & Bespoke AI \\
    \end{tabular}
  \end{center}
}

% ══ FOOTER / KEY MESSAGE ══
\posterbox[
  enhanced, colback=secondary, colframe=secondary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=footer, column=1, span=3, between=row22 and bottom}{
  {\fontsize{24}{30}\selectfont\bfseries\textcolor{textwhite}{
    One Ecosystem. Infinite Possibilities. Powered by AI.}}
}

\end{tcbposter}
\end{document}

